/* Offline support for the arcade. Generated by tools/update-sw.py: edit tools/sw-template.js, not sw.js.
   - install: download every page, icon and small picture in one go (the install only succeeds if all of them were saved)
   - pages: come fresh from the network when online (so updates show straight away), falling back to the saved copy if
     the network is slow or offline
   - stamped files (address ends ?v=<fingerprint>): a stamp never changes, so once saved they're served straight from
     the saved copy, and kept across versions in their own store; a new stamp for the same file replaces the old one
   - anything else: answer from the saved copy and refresh it quietly
   - activate: delete the copies saved by older versions
   - a page can ask which version is running: postMessage('version') */
const VERSION = 'games-34273264360d';
const STAMPED = 'bb-stamped';
const FILES = [
  './',
  './manifest.webmanifest',
  './icons/apple-touch-icon.png?v=0ef76193',
  './icons/bean.png?v=2ef68eca',
  './icons/bear.png?v=406624f3',
  './icons/favicon-32.png?v=aada1fbe',
  './icons/icon-192.png?v=01a66771',
  './icons/icon-512.png?v=2701a8de',
  './icons/logo.jpg?v=4530529b',
  './icons/maskable-512.png?v=f18c0bbd',
  './bean-2048/',
  './bumble-dash/',
  './crystal-cave/',
  './dot-loop/',
  './dots-and-boxes/',
  './find-a-flower/',
  './fishy-floes/',
  './greedy-hippos/',
  './guess-five/',
  './gummy-pop/',
  './hedge-hop/',
  './hide-and-seek/',
  './hue-quilt/',
  './ink-bounce/',
  './lace-loops/',
  './paw-pairs/',
  './paw-prints/',
  './pyramid-hop/',
  './queen-bean/',
  './sand-sort/',
  './slither-slide/',
  './stack-drop/',
  './sudoku/',
  './tangle-tails/',
  './thin-ice/',
  './tile-burst/',
  './word-hive/',
  './find-a-flower/bear-and-bean-picnic.webp?v=53b8e142'
];

self.addEventListener('install', event => {
  event.waitUntil((async () => {
    const pages = await caches.open(VERSION), stamped = await caches.open(STAMPED);
    await Promise.all(FILES.map(async url => {
      const isStamped = url.includes('?v=');
      if (isStamped && await stamped.match(url)) return;   // already have this exact file
      const res = await fetch(new Request(url, { cache: 'reload' }));
      if (!res.ok) throw new Error('could not save ' + url);
      await (isStamped ? stamped : pages).put(url, res);
    }));
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', event => {
  event.waitUntil(
    caches.keys()
      .then(keys => Promise.all(keys.filter(k => k.startsWith('games-') && k !== VERSION).map(k => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener('message', event => {
  if (event.data === 'version' && event.ports[0]) event.ports[0].postMessage(VERSION);
});

async function stampedFile(req, url) {
  const store = await caches.open(STAMPED);
  const saved = await store.match(url.href);
  if (saved) return saved;
  const res = await fetch(req).catch(() => null);
  if (res && res.ok && res.type === 'basic') {
    // keep only the newest stamp of each file
    for (const old of await store.keys()) { const u = new URL(old.url); if (u.pathname === url.pathname && u.href !== url.href) store.delete(old); }
    await store.put(url.href, res.clone());
  }
  return res || Response.error();
}

self.addEventListener('fetch', event => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  if (url.pathname.endsWith('/sw.js')) return;   // always ask the network, so version checks are honest
  if (req.mode !== 'navigate' && url.searchParams.has('v')) { event.respondWith(stampedFile(req, url)); return; }
  // one key per page: ignore ?query and treat folder/index.html as folder/
  let path = url.pathname;
  if (path.endsWith('/index.html')) path = path.slice(0, -'index.html'.length);
  const key = new Request(url.origin + path);
  event.respondWith((async () => {
    const cache = await caches.open(VERSION);
    const saved = await cache.match(key);
    const fresh = fetch(req, req.mode === 'navigate' ? { cache: 'no-cache' } : undefined).then(res => {
      if (res && res.ok && res.type === 'basic') cache.put(key, res.clone());
      return res;
    }).catch(() => null);
    if (saved && req.mode === 'navigate') {
      // give the network a few seconds to bring the newest page; otherwise use the saved one
      const quick = await Promise.race([fresh, new Promise(r => setTimeout(() => r(null), 3000))]);
      // a fresh page, or a redirect (the site moved): let the browser follow it rather than keep the old copy
      if (quick && (quick.ok || quick.type === 'opaqueredirect' || quick.redirected)) return quick;
      event.waitUntil(fresh); return saved;
    }
    if (saved) { event.waitUntil(fresh); return saved; }
    const res = await fresh;
    if (res) return res;
    if (req.mode === 'navigate') return (await cache.match(new Request(new URL('./', self.location).href))) || Response.error();
    return Response.error();
  })());
});
